sealed interface WirePayment permits CsvPayment, XmlPayment, LegacyPayment {}
record CsvPayment(String raw) implements WirePayment {}
record XmlPayment(String document) implements WirePayment {}

static Payment canonical(WirePayment w) {
    return switch (w) {                       // exhaustive: compiler-checked
        case CsvPayment c    -> CsvMap.toPayment(c.raw());
        case XmlPayment x    -> XmlMap.toPayment(x.document());
        case LegacyPayment l -> LegacyMap.toPayment(l.record());
    };
}
